inbound.set-body:
@{
            var req = (JObject)context.Variables["anthropicRequest"];
            var oai = new JObject();
            oai["model"] = (string)context.Variables["deployment"];

            var msgs = new JArray();

            // --- system: cadena o array de bloques -> mensaje role=system ---
            var sys = req["system"];
            if (sys != null && sys.Type != JTokenType.Null)
            {
                string sysText;
                if (sys.Type == JTokenType.String)
                {
                    sysText = (string)sys;
                }
                else
                {
                    var parts = new List<string>();
                    if (sys.Type == JTokenType.Array)
                    {
                        foreach (var b in (JArray)sys)
                        {
                            if ((string)b["type"] == "text" && b["text"] != null) { parts.Add((string)b["text"]); }
                        }
                    }
                    sysText = string.Join("\n\n", parts);
                }
                if (!string.IsNullOrWhiteSpace(sysText))
                {
                    var sm = new JObject();
                    sm["role"] = "system";
                    sm["content"] = sysText;
                    msgs.Add(sm);
                }
            }

            // --- messages ---
            var inMsgs = req["messages"] as JArray;
            if (inMsgs != null)
            {
                foreach (var msgTok in inMsgs)
                {
                    var msg = (JObject)msgTok;
                    var role = (string)msg["role"];
                    var content = msg["content"];
                    if (content == null || content.Type == JTokenType.Null) { continue; }

                    // content como cadena simple
                    if (content.Type == JTokenType.String)
                    {
                        var sm = new JObject();
                        sm["role"] = role;
                        sm["content"] = (string)content;
                        msgs.Add(sm);
                        continue;
                    }

                    // content como array de bloques
                    var textParts = new List<string>();
                    var imageParts = new JArray();
                    var toolCalls = new JArray();
                    var toolResultMsgs = new JArray();

                    foreach (var blkTok in (JArray)content)
                    {
                        var blk = (JObject)blkTok;
                        var btype = (string)blk["type"];

                        if (btype == "text")
                        {
                            if (blk["text"] != null) { textParts.Add((string)blk["text"]); }
                        }
                        else if (btype == "image")
                        {
                            // Anthropic base64 -> data URL de OpenAI
                            var src = blk["source"] as JObject;
                            if (src != null)
                            {
                                string url = null;
                                if ((string)src["type"] == "base64")
                                {
                                    url = "data:" + (string)src["media_type"] + ";base64," + (string)src["data"];
                                }
                                else if ((string)src["type"] == "url")
                                {
                                    url = (string)src["url"];
                                }
                                if (url != null)
                                {
                                    var iu = new JObject();
                                    iu["url"] = url;
                                    var ip = new JObject();
                                    ip["type"] = "image_url";
                                    ip["image_url"] = iu;
                                    imageParts.Add(ip);
                                }
                            }
                        }
                        else if (btype == "tool_use")
                        {
                            var fn = new JObject();
                            fn["name"] = (string)blk["name"];
                            var input = blk["input"];
                            fn["arguments"] = input == null || input.Type == JTokenType.Null
                                ? "{}"
                                : input.ToString(Newtonsoft.Json.Formatting.None);
                            var tc = new JObject();
                            tc["id"] = (string)blk["id"];
                            tc["type"] = "function";
                            tc["function"] = fn;
                            toolCalls.Add(tc);
                        }
                        else if (btype == "tool_result")
                        {
                            var c = blk["content"];
                            string ctext;
                            if (c == null || c.Type == JTokenType.Null) { ctext = ""; }
                            else if (c.Type == JTokenType.String) { ctext = (string)c; }
                            else if (c.Type == JTokenType.Array)
                            {
                                var cparts = new List<string>();
                                foreach (var cb in (JArray)c)
                                {
                                    if ((string)cb["type"] == "text" && cb["text"] != null) { cparts.Add((string)cb["text"]); }
                                }
                                ctext = string.Join("\n", cparts);
                            }
                            else { ctext = c.ToString(Newtonsoft.Json.Formatting.None); }

                            if ((bool?)blk["is_error"] == true) { ctext = "ERROR: " + ctext; }

                            var tr = new JObject();
                            tr["role"] = "tool";
                            tr["tool_call_id"] = (string)blk["tool_use_id"];
                            tr["content"] = ctext;
                            toolResultMsgs.Add(tr);
                        }
                    }

                    // Los tool_result son mensajes role=tool independientes y van primero,
                    // porque OpenAI exige que sigan inmediatamente al assistant con tool_calls.
                    foreach (var tr in toolResultMsgs) { msgs.Add(tr); }

                    if (role == "assistant")
                    {
                        if (textParts.Count > 0 || toolCalls.Count > 0)
                        {
                            var am = new JObject();
                            am["role"] = "assistant";
                            if (textParts.Count > 0) { am["content"] = string.Join("\n", textParts); }
                            else { am["content"] = null; }
                            if (toolCalls.Count > 0) { am["tool_calls"] = toolCalls; }
                            msgs.Add(am);
                        }
                    }
                    else
                    {
                        if (imageParts.Count > 0)
                        {
                            // Multimodal: content como array de partes
                            var parts = new JArray();
                            if (textParts.Count > 0)
                            {
                                var tp = new JObject();
                                tp["type"] = "text";
                                tp["text"] = string.Join("\n", textParts);
                                parts.Add(tp);
                            }
                            foreach (var ip in imageParts) { parts.Add(ip); }
                            var um = new JObject();
                            um["role"] = role;
                            um["content"] = parts;
                            msgs.Add(um);
                        }
                        else if (textParts.Count > 0)
                        {
                            var um = new JObject();
                            um["role"] = role;
                            um["content"] = string.Join("\n", textParts);
                            msgs.Add(um);
                        }
                    }
                }
            }

            oai["messages"] = msgs;

            // --- parámetros de muestreo ---
            // max_tokens es obligatorio en Anthropic; se acota al máximo de salida del modelo.
            var maxTok = req["max_tokens"] != null ? (int)req["max_tokens"] : 4096;
            if (maxTok > 16384) { maxTok = 16384; }
            if (maxTok < 1) { maxTok = 1; }
            oai["max_tokens"] = maxTok;

            if (req["temperature"] != null) { oai["temperature"] = req["temperature"]; }
            if (req["top_p"] != null) { oai["top_p"] = req["top_p"]; }
            var stopSeq = req["stop_sequences"] as JArray;
            if (stopSeq != null && stopSeq.Count > 0) { oai["stop"] = stopSeq; }

            // --- tools: input_schema -> parameters ---
            var tools = req["tools"] as JArray;
            if (tools != null && tools.Count > 0)
            {
                var oaiTools = new JArray();
                foreach (var tTok in tools)
                {
                    var t = (JObject)tTok;
                    if (t["name"] == null) { continue; }
                    var fn = new JObject();
                    fn["name"] = (string)t["name"];
                    if (t["description"] != null) { fn["description"] = (string)t["description"]; }
                    var schema = t["input_schema"];
                    fn["parameters"] = schema != null && schema.Type == JTokenType.Object ? schema : new JObject();
                    var wrap = new JObject();
                    wrap["type"] = "function";
                    wrap["function"] = fn;
                    oaiTools.Add(wrap);
                }
                if (oaiTools.Count > 0)
                {
                    oai["tools"] = oaiTools;
                    var tc = req["tool_choice"] as JObject;
                    if (tc != null)
                    {
                        var tct = (string)tc["type"];
                        if (tct == "auto") { oai["tool_choice"] = "auto"; }
                        else if (tct == "any") { oai["tool_choice"] = "required"; }
                        else if (tct == "none") { oai["tool_choice"] = "none"; }
                        else if (tct == "tool" && tc["name"] != null)
                        {
                            var f = new JObject();
                            f["name"] = (string)tc["name"];
                            var w = new JObject();
                            w["type"] = "function";
                            w["function"] = f;
                            oai["tool_choice"] = w;
                        }
                    }
                }
            }

            // El backend se llama siempre sin streaming; el SSE se sintetiza en outbound.
            oai["stream"] = false;
            return oai.ToString(Newtonsoft.Json.Formatting.None);
        }

set-variable.value:
