when.set-body:
@{
                            var resp = (JObject)context.Variables["anthropicResponse"];
                            var content = (JArray)resp["content"];
                            var usage = (JObject)resp["usage"];
                            var fmt = Newtonsoft.Json.Formatting.None;
                            var sse = new List<string>();

                            // message_start: mismo mensaje pero sin contenido y sin stop_reason
                            var startMsg = (JObject)resp.DeepClone();
                            startMsg["content"] = new JArray();
                            startMsg["stop_reason"] = null;
                            ((JObject)startMsg["usage"])["output_tokens"] = 0;
                            var ev = new JObject();
                            ev["type"] = "message_start";
                            ev["message"] = startMsg;
                            sse.Add("event: message_start\ndata: " + ev.ToString(fmt) + "\n\n");

                            for (int i = 0; i < content.Count; i++)
                            {
                                var blk = (JObject)content[i];
                                var btype = (string)blk["type"];

                                var startBlk = new JObject();
                                var deltaEv = new JObject();

                                if (btype == "tool_use")
                                {
                                    var cb = new JObject();
                                    cb["type"] = "tool_use";
                                    cb["id"] = blk["id"];
                                    cb["name"] = blk["name"];
                                    cb["input"] = new JObject();
                                    startBlk["type"] = "content_block_start";
                                    startBlk["index"] = i;
                                    startBlk["content_block"] = cb;

                                    var d = new JObject();
                                    d["type"] = "input_json_delta";
                                    d["partial_json"] = blk["input"].ToString(fmt);
                                    deltaEv["type"] = "content_block_delta";
                                    deltaEv["index"] = i;
                                    deltaEv["delta"] = d;
                                }
                                else
                                {
                                    var cb = new JObject();
                                    cb["type"] = "text";
                                    cb["text"] = "";
                                    startBlk["type"] = "content_block_start";
                                    startBlk["index"] = i;
                                    startBlk["content_block"] = cb;

                                    var d = new JObject();
                                    d["type"] = "text_delta";
                                    d["text"] = (string)blk["text"];
                                    deltaEv["type"] = "content_block_delta";
                                    deltaEv["index"] = i;
                                    deltaEv["delta"] = d;
                                }

                                var stopBlk = new JObject();
                                stopBlk["type"] = "content_block_stop";
                                stopBlk["index"] = i;

                                sse.Add("event: content_block_start\ndata: " + startBlk.ToString(fmt) + "\n\n");
                                sse.Add("event: content_block_delta\ndata: " + deltaEv.ToString(fmt) + "\n\n");
                                sse.Add("event: content_block_stop\ndata: " + stopBlk.ToString(fmt) + "\n\n");
                            }

                            var md = new JObject();
                            md["stop_reason"] = resp["stop_reason"];
                            md["stop_sequence"] = null;
                            var mu = new JObject();
                            mu["output_tokens"] = usage["output_tokens"];
                            var mdEv = new JObject();
                            mdEv["type"] = "message_delta";
                            mdEv["delta"] = md;
                            mdEv["usage"] = mu;
                            sse.Add("event: message_delta\ndata: " + mdEv.ToString(fmt) + "\n\n");

                            var msEv = new JObject();
                            msEv["type"] = "message_stop";
                            sse.Add("event: message_stop\ndata: " + msEv.ToString(fmt) + "\n\n");

                            return string.Join("", sse);
                        }

otherwise.set-body:
@{
                    var code = context.Response.StatusCode;
                    string etype = "api_error";
                    if (code == 400) { etype = "invalid_request_error"; }
                    else if (code == 401) { etype = "authentication_error"; }
                    else if (code == 403) { etype = "permission_error"; }
                    else if (code == 404) { etype = "not_found_error"; }
                    else if (code == 429) { etype = "rate_limit_error"; }
                    else if (code >= 500) { etype = "api_error"; }

                    string message = "Upstream error " + code;
                    try
                    {
                        var body = context.Response.Body.As<JObject>(preserveContent: true);
                        if (body["error"] != null && body["error"]["message"] != null)
                        {
                            message = (string)body["error"]["message"];
                        }
                        else if (body["message"] != null) { message = (string)body["message"]; }
                    }
                    catch { }

                    var err = new JObject();
                    err["type"] = etype;
                    err["message"] = message;
                    var wrap = new JObject();
                    wrap["type"] = "error";
                    wrap["error"] = err;
                    return wrap.ToString(Newtonsoft.Json.Formatting.None);
                }
